80	@RestController
81	@CrossOrigin(exposedHeaders = "errors, content-type")
82	@RequestMapping("/api")
83	public class OwnerRestControllerV1 implements OwnersApi {
84	
85	    /**
86	     * Dedicated audit logger. A successful owner create emits here, independently of the application
87	     * log: first a human-readable line carrying the new owner's id, member id, registration date
88	     * and membership level, then the immutable structured {@code OWNER_CREATED} event (see
89	     * {@link OwnerCreatedEvent}) as a compact JSON object.
90	     */
91	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
92	
93	    /**
94	     * Dedicated notification logger. On a successful owner create a welcome notification is enqueued
95	     * here, emitting a single line carrying the new owner's id and member id.
96	     */
97	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
98	
99	    /**
100	     * Process-wide sequence backing the {@code seq} of the structured {@code OWNER_CREATED} event. It
101	     * is incremented once per successful create so each emitted event carries a strictly larger,
102	     * monotonically increasing sequence number than the one before it.
103	     */
104	    private static final AtomicInteger AUDIT_SEQUENCE = new AtomicInteger();
105	
106	    private final ClinicService clinicService;
107	
108	    private final OwnerMapper ownerMapper;
109	
110	    private final PetMapper petMapper;
111	
112	    private final VisitMapper visitMapper;
113	
114	    /**
115	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
116	     * and a domain containing at least one dot, with no whitespace in any segment.
117	     */
118	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
119	
120	    /**
121	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email address
122	     * is on this blocklist (compared case-insensitively on the domain, the part after the final
123	     * {@code '@'}) is rejected with a 400 Bad Request.
124	     */
125	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
126	        "mailinator.com",
127	        "tempmail.com",
128	        "guerrillamail.com");
129	
130	    /**
131	     * Required national-number length per E.164 country code. A normalized telephone whose country
132	     * code appears here must carry exactly this many national digits after the code; Australia
133	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
134	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
135	     */
136	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
137	
138	    /**
139	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
140	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
141	     */
142	    private static final int MAX_OWNERS_PER_CITY = 50;
143	
144	    /**
145	     * Lower bound of the per-city capacity-warning band. When a city already holds at least this many
146	     * but fewer than {@value #MAX_OWNERS_PER_CITY} owners it is approaching capacity, and a create in
147	     * that city is flagged ({@code capacityWarning} true); the hard rejection at
148	     * {@value #MAX_OWNERS_PER_CITY} is unaffected.
149	     */
150	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
151	
152	    /**
153	     * Maximum number of owners that may be registered on a single day (by registration date). A create
154	     * attempted once this many owners already carry today's registration date is rejected with a
155	     * 429 Too Many Requests.
156	     */
157	    private static final int MAX_OWNERS_PER_DAY = 100;
158	
159	    /**
160	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
161	     * owners already carry the new owner's registration date, the created owner is flagged
162	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
163	     */
164	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
165	
166	    /**
167	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
168	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
169	     */
170	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
171	        "ST", "STREET",
172	        "RD", "ROAD",
173	        "AVE", "AVENUE");
174	
175	    /**
176	     * Inclusive 4-digit postcode range permitted per region, keyed by the region derived from the
177	     * owner's city ({@link Owner#getLocality()}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
178	     * region not listed (the {@code 'UNKNOWN'} locality of a city with no known region) accepts any
179	     * 4-digit postcode.
180	     */
181	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
182	        "NSW", new int[] {2000, 2099},
183	        "VIC", new int[] {3000, 3099},
184	        "QLD", new int[] {4000, 4099});
185	
186	    /**
187	     * Name of the request header that carries the client-supplied idempotency key for an owner create.
188	     * When a create repeats with a key already seen, the originally created owner is returned with
189	     * {@code 200 OK} instead of a second owner being created.
190	     */
191	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
192	
193	    /**
194	     * Remembers, per idempotency key, the id of the owner created by the first request that carried that
195	     * key, so a later create repeating the same key can return the original owner instead of creating a
196	     * duplicate. The key space is the client-supplied {@code Idempotency-Key} header value.
197	     */
198	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
199	
200	    public OwnerRestControllerV1(ClinicService clinicService,
201	                                 OwnerMapper ownerMapper,
202	                                 PetMapper petMapper,
203	                                 VisitMapper visitMapper) {
204	        this.clinicService = clinicService;
205	        this.ownerMapper = ownerMapper;
206	        this.petMapper = petMapper;
207	        this.visitMapper = visitMapper;
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
213	        Collection<Owner> owners;
214	        if (lastName != null) {
215	            owners = this.clinicService.findOwnerByLastName(lastName);
216	        } else {
217	            owners = this.clinicService.findAllOwners();
218	        }
219	        if (owners.isEmpty()) {
220	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	        }
222	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
223	    }
224	
225	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
226	    @Override
227	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
228	        Owner owner = this.clinicService.findOwnerById(ownerId);
229	        if (owner == null) {
230	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	        }
232	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
233	    }
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
238	        String idempotencyKey = currentIdempotencyKey();
239	        OwnerDto replayed = replayIfSeen(idempotencyKey);
240	        if (replayed != null) {
241	            return new ResponseEntity<>(replayed, HttpStatus.OK);
242	        }
243	        validateRequiredFields(ownerFieldsDto);
244	        HttpHeaders headers = new HttpHeaders();
245	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
246	        rejectFutureRegistrationDate(owner.getRegistrationDate());
247	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
248	        owner.setRegistrationDate(registrationDate);
249	        requireDailyCapacity(registrationDate);
250	        long cityOwnerCount = countOwnersInCity(owner.getCity());
251	        requireCityHasCapacity(owner.getCity(), cityOwnerCount);
252	        owner.setCapacityWarning(isApproachingCityCapacity(cityOwnerCount));
253	        validatePostcode(owner);
254	        applyAddress(owner, ownerFieldsDto);
255	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
256	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
257	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
258	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
259	        requireUniqueIdentity(owner);
260	        flagPossibleDuplicate(owner, declaredHouseholdMember);
261	        owner.setMemberId(deduplicateMemberId(owner.buildMemberId()));
262	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
263	        stampHouseholdSize(owner);
264	        capMembershipLevelToHousehold(owner);
265	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
266	        this.clinicService.saveOwner(owner);
267	        rememberCreate(idempotencyKey, owner);
268	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
269	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
270	        emitOwnerCreatedEvent(owner);
271	        enqueueWelcomeNotification(owner);
272	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
273	        headers.setLocation(UriComponentsBuilder.newInstance()
274	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
275	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
276	    }
277	
278	    /**
279	     * Emits the immutable structured {@code OWNER_CREATED} event to the {@link #AUDIT} logger as a
280	     * compact JSON object, alongside the human-readable audit line. The event's {@code seq} is drawn
281	     * from the process-wide {@link #AUDIT_SEQUENCE}, so it strictly increases across creates, and it
282	     * carries both the owner's id and its current primary identifier via
283	     * {@link #primaryIdentifier(Owner)}.
284	     *
285	     * @param owner the owner that was just created and saved
286	     */
287	    private void emitOwnerCreatedEvent(Owner owner) {
288	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQUENCE.incrementAndGet(),
289	            owner.getId(), owner.getMemberId(), owner.getMembershipLevel());
290	        AUDIT.info(event.toJson());
291	    }
292	
293	    /**
294	     * Enqueues a welcome notification for a just-created owner by emitting a single line to the
295	     * {@link #NOTIFY} logger carrying the owner's id and its member id.
296	     *
297	     * @param owner the owner that was just created and saved
298	     */
299	    private void enqueueWelcomeNotification(Owner owner) {
300	        NOTIFY.info("Welcome owner: id={} memberId={}", owner.getId(), owner.getMemberId());
301	    }
302	
303	    /**
304	     * The immutable structured event emitted on a successful owner create. {@code seq} is the
305	     * process-wide monotonically increasing sequence across creates; {@code ownerId} is the new
306	     * owner's id; {@code memberId} carries the owner's unified member id; {@code membershipLevel} is
307	     * the owner's membership level. It serializes to a compact JSON object whose {@code event} is
308	     * always {@value #EVENT_TYPE}.
309	     *
310	     * @param seq the monotonically increasing create sequence number
311	     * @param ownerId the created owner's id
312	     * @param memberId the owner's unified member id
313	     * @param membershipLevel the owner's membership level
314	     */
315	    private record OwnerCreatedEvent(int seq, Integer ownerId, String memberId, Integer membershipLevel) {
316	
317	        /** The fixed {@code event} discriminator carried by every emitted event. */
318	        private static final String EVENT_TYPE = "OWNER_CREATED";
319	
320	        /** Shared, thread-safe mapper used only to serialize the event to its JSON form. */
321	        private static final ObjectMapper MAPPER = JsonMapper.builder().build();
322	
323	        /**
324	         * Serializes this event to its compact JSON form
325	         * {@code {seq, ownerId, memberId, membershipLevel, event}}, with the fields in that order.
326	         *
327	         * @return the event as a JSON object string
328	         */
329	        private String toJson() {
330	            Map<String, Object> fields = new LinkedHashMap<>();
331	            fields.put("seq", this.seq);
332	            fields.put("ownerId", this.ownerId);
333	            fields.put("memberId", this.memberId);
334	            fields.put("membershipLevel", this.membershipLevel);
335	            fields.put("event", EVENT_TYPE);
336	            return MAPPER.writeValueAsString(fields);
337	        }
338	    }
339	
340	    /**
341	     * Reads the client-supplied idempotency key from the current request's {@code Idempotency-Key}
342	     * header. Returns {@code null} when the header is absent or blank (the create is not idempotent),
343	     * or when no servlet request is bound to the current thread.
344	     *
345	     * <p>The header is read from the bound request rather than taken as a {@code @RequestHeader} method
346	     * parameter because {@code addOwner}'s signature is fixed by the generated {@link OwnersApi}
347	     * interface and cannot carry an extra parameter.
348	     *
349	     * @return the trimmed idempotency key, or {@code null} when none was supplied
350	     */
351	    private String currentIdempotencyKey() {
352	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
353	            String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
354	            if (StringUtils.hasText(key)) {
355	                return key.trim();
356	            }
357	        }
358	        return null;
359	    }
360	
361	    /**
362	     * Returns the owner originally created under the given idempotency key, so a create repeating a
363	     * key already seen replays the first result instead of creating a duplicate. Yields {@code null}
364	     * when there is no key, the key has not been seen, or the remembered owner no longer exists (in
365	     * which case the create proceeds normally).
366	     *
367	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
368	     * @return the originally created owner as a DTO, or {@code null} when there is nothing to replay
369	     */
370	    private OwnerDto replayIfSeen(String idempotencyKey) {
371	        if (idempotencyKey == null) {
372	            return null;
373	        }
374	        Integer existingId = idempotentCreates.get(idempotencyKey);
375	        if (existingId == null) {
376	            return null;
377	        }
378	        Owner existing = this.clinicService.findOwnerById(existingId);
379	        return existing == null ? null : ownerMapper.toOwnerDto(existing);
380	    }
381	
382	    /**
383	     * Remembers the id of a just-created owner against the idempotency key that produced it, so a later
384	     * create repeating the same key can be replayed by {@link #replayIfSeen}. A {@code null} key (the
385	     * create was not idempotent) is ignored.
386	     *
387	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
388	     * @param owner the owner that was just created and saved
389	     */
390	    private void rememberCreate(String idempotencyKey, Owner owner) {
391	        if (idempotencyKey != null) {
392	            idempotentCreates.put(idempotencyKey, owner.getId());
393	        }
394	    }
395	
396	    /**
397	     * Rejects a create whose supplied registration date is later than the server's current date. A
398	     * registration may be back-dated but never post-dated, so a future date is treated as a client
399	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
400	     * server date.
401	     *
402	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
403	     *     client omitted it
404	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
405	     */
406	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
407	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
408	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
409	        }
410	    }
411	
412	    /**
413	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
414	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
415	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
416	     * existed prior to this create.
417	     *
418	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
419	     *     a business day
420	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
421	     *     registered on that business day
422	     */
423	    private void requireDailyCapacity(LocalDate registrationDate) {
424	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
425	            throw new DailyOwnerLimitException(registrationDate);
426	        }
427	    }
428	
429	    /**
430	     * Counts the existing owners whose registration date equals the given business-day date. This is
431	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
432	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
433	     * the bulk-signup warning.
434	     *
435	     * @param registrationDate the effective business-day registration date to count against
436	     * @return the number of pre-existing owners registered on that date
437	     */
438	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
439	        return this.clinicService.findAllOwners().stream()
440	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
441	            .count();
442	    }
443	
444	    /**
445	     * Rejects an owner whose city already contains the maximum allowed number of owners
446	     * ({@value #MAX_OWNERS_PER_CITY}). The count is supplied by {@link #countOwnersInCity(String)} and
447	     * reflects only the owners that existed prior to this create.
448	     *
449	     * @param city the city of the owner being created
450	     * @param cityOwnerCount the number of pre-existing owners already in that city
451	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
452	     */
453	    private void requireCityHasCapacity(String city, long cityOwnerCount) {
454	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
455	            throw new CityOwnerLimitException(city);
456	        }
457	    }
458	
459	    /**
460	     * Counts the existing owners whose city equals the given city, compared case-insensitively. This is
461	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to this
462	     * create. It is the single definition of the per-city count shared by the city hard-limit rule and
463	     * the approaching-capacity warning.
464	     *
465	     * @param city the city of the owner being created
466	     * @return the number of pre-existing owners in that city
467	     */
468	    private long countOwnersInCity(String city) {
469	        return this.clinicService.findAllOwners().stream()
470	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
471	            .count();
472	    }
473	
474	    /**
475	     * Whether a city holding the given number of owners is approaching the per-city capacity limit: at
476	     * least {@value #CITY_CAPACITY_WARNING_THRESHOLD} but fewer than {@value #MAX_OWNERS_PER_CITY}. A
477	     * create in such a city is flagged ({@code capacityWarning} true); the hard rejection at
478	     * {@value #MAX_OWNERS_PER_CITY} is unaffected.
479	     *
480	     * @param cityOwnerCount the number of pre-existing owners already in the city
481	     * @return whether the city is in the 40-49 approaching-capacity band
482	     */
483	    private boolean isApproachingCityCapacity(long cityOwnerCount) {
484	        return cityOwnerCount >= CITY_CAPACITY_WARNING_THRESHOLD && cityOwnerCount < MAX_OWNERS_PER_CITY;
485	    }
486	
487	    /**
488	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
489	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
490	     * schema) that must fall within the inclusive range permitted for the region derived from the
491	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
492	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
493	     *
494	     * @param owner the owner being created, with its city and postcode set
495	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
496	     */
497	    private void validatePostcode(Owner owner) {
498	        String postcode = owner.getPostcode();
499	        if (postcode == null) {
500	            return;
501	        }
502	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
503	        if (range == null) {
504	            return;
505	        }
506	        int value = Integer.parseInt(postcode);
507	        if (value < range[0] || value > range[1]) {
508	            throw new InvalidOwnerFieldsException(List.of("postcode"));
509	        }
510	    }
511	
512	    /**
513	     * Counts the existing owners that already share the given first name and last name, compared
514	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
515	     * owners that existed prior to this create.
516	     *
517	     * @param firstName the first name of the owner being created
518	     * @param lastName the last name of the owner being created
519	     * @return the number of pre-existing namesakes
520	     */
521	    private int countNamesakes(String firstName, String lastName) {
522	        return (int) this.clinicService.findAllOwners().stream()
523	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
524	                && equalsIgnoreCase(existing.getLastName(), lastName))
525	            .count();
526	    }
527	
528	    /**
529	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
530	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
531	     *
532	     * @param a the first value, possibly {@code null}
533	     * @param b the second value, possibly {@code null}
534	     * @return whether the values are equal ignoring case
535	     */
536	    private boolean equalsIgnoreCase(String a, String b) {
537	        return a == null ? b == null : a.equalsIgnoreCase(b);
538	    }
539	
540	    /**
541	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
542	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
543	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
544	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
545	     *
546	     * @param ownerFieldsDto the submitted owner fields
547	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
548	     */
549	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
550	        List<String> invalidFields = new ArrayList<>();
551	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
552	            invalidFields.add("firstName");
553	        }
554	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
555	            invalidFields.add("lastName");
556	        }
557	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddressLine1()))
558	            && !StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
559	            invalidFields.add("address");
560	        }
561	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
562	            invalidFields.add("city");
563	        }
564	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
565	            invalidFields.add("telephone");
566	        }
567	        if (!invalidFields.isEmpty()) {
568	            throw new InvalidOwnerFieldsException(invalidFields);
569	        }
570	    }
571	
572	    /**
573	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
574	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
575	     * what gets stored and returned.
576	     *
577	     * @param telephone the raw telephone value from the request
578	     * @return the normalized E.164 telephone number
579	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
580	     */
581	    private String normalizeTelephone(String telephone) {
582	        String e164 = toE164(telephone);
583	        if (e164 == null) {
584	            throw new InvalidOwnerFieldsException(List.of("telephone"));
585	        }
586	        return e164;
587	    }
588	
589	    /**
590	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
591	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
592	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
593	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
594	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
595	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
596	     *
597	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
598	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
599	     *
600	     * @param telephone the raw telephone value, possibly {@code null}
601	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
602	     */
603	    private String toE164(String telephone) {
604	        if (telephone == null) {
605	            return null;
606	        }
607	        String cleaned = telephone.replaceAll("[ \\-()]", "");
608	        String digits;
609	        if (cleaned.startsWith("+")) {
610	            digits = cleaned.substring(1);
611	        } else {
612	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
613	            digits = "61" + national;
614	        }
615	        if (!digits.matches("[0-9]{8,15}")) {
616	            return null;
617	        }
618	        if (!nationalNumberLengthValid(digits)) {
619	            return null;
620	        }
621	        return "+" + digits;
622	    }
623	
624	    /**
625	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
626	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
627	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
628	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
629	     * accepted, leaving only the generic total-length rule to apply.
630	     *
631	     * @param digits the E.164 digits without the leading {@code '+'}
632	     * @return {@code true} if the national-number length matches the country code's requirement
633	     */
634	    private boolean nationalNumberLengthValid(String digits) {
635	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
636	            String code = entry.getKey();
637	            if (digits.startsWith(code)) {
638	                return digits.length() - code.length() == entry.getValue();
639	            }
640	        }
641	        return true;
642	    }
643	
644	    /**
645	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
646	     * {@code null}. When present, the value must be a syntactically valid address whose domain is not
647	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); it is then stored and
648	     * returned lower-cased.
649	     *
650	     * @param email the raw email value from the request, possibly {@code null}
651	     * @return the lower-cased email, or {@code null} when none was supplied
652	     * @throws InvalidOwnerFieldsException if a value is present but is not a valid email address or
653	     *     its domain is on the disposable-domain blocklist
654	     */
655	    private String normalizeEmail(String email) {
656	        if (!StringUtils.hasText(email)) {
657	            return null;
658	        }
659	        String trimmed = email.trim();
660	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
661	            throw new InvalidOwnerFieldsException(List.of("email"));
662	        }
663	        String normalized = trimmed.toLowerCase(Locale.ROOT);
664	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
665	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
666	            throw new InvalidOwnerFieldsException(List.of("email"));
667	        }
668	        return normalized;
669	    }
670	
671	    /**
672	     * Rejects an owner whose whole identity key is already used by an existing (non-deleted) owner.
673	     * This is the single consolidated duplicate check: the identity key
674	     * ({@link Owner#getIdentityKey()}) is the lower-case SHA-256 hex of the owner's normalized
675	     * telephone, lower-cased email (empty when absent) and the Soundex of its last name joined with
676	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
677	     * owner's. Because the telephone is part of the key, two owners sharing a last name and postcode
678	     * but carrying different telephones have different identity keys and are both allowed (the second
679	     * is flagged a soft match by {@link #flagPossibleDuplicate}). Owners flagged deleted are ignored.
680	     *
681	     * @param owner the owner being created, with its normalized telephone, email and last name set
682	     * @throws DuplicateIdentityException if another owner already has this identity key
683	     */
684	    private void requireUniqueIdentity(Owner owner) {
685	        String identityKey = owner.getIdentityKey();
686	        boolean inUse = this.clinicService.findAllOwners().stream()
687	            .filter(existing -> !existing.isDeleted())
688	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
689	        if (inUse) {
690	            throw new DuplicateIdentityException(identityKey);
691	        }
692	    }
693	
694	    /**
695	     * De-duplicates a newly computed member id against the ids already held by existing owners. When
696	     * the computed id is unique it is returned unchanged. When it collides with an existing owner's
697	     * {@code memberId}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that makes
698	     * the result unique (so a second collision yields {@code '-2'}, a third {@code '-3'}, and so on),
699	     * and that de-duplicated id is returned.
700	     *
701	     * @param memberId the freshly computed member id to de-duplicate
702	     * @return a member id not held by any existing owner
703	     */
704	    private String deduplicateMemberId(String memberId) {
705	        Set<String> inUse = this.clinicService.findAllOwners().stream()
706	            .map(Owner::getMemberId)
707	            .filter(Objects::nonNull)
708	            .collect(Collectors.toSet());
709	        if (!inUse.contains(memberId)) {
710	            return memberId;
711	        }
712	        int n = 2;
713	        String candidate;
714	        do {
715	            candidate = memberId + "-" + n;
716	            n++;
717	        } while (inUse.contains(candidate));
718	        return candidate;
719	    }
720	
721	    /**
722	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
723	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
724	     * but it shares an existing owner's last-name {@linkplain Soundex#encode(String) Soundex} and postcode
725	     * (both present and equal) while carrying a different identity key. When such an existing owner is
726	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
727	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
728	     * is false and {@code possibleDuplicateOf} is left unset.
729	     *
730	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
731	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
732	     *
733	     * @param owner the owner being created, with its normalized telephone, email, last name and postcode set
734	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
735	     */
736	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
737	        if (declaredHouseholdMember || owner.getPostcode() == null) {
738	            owner.setPossibleDuplicate(false);
739	            return;
740	        }
741	        String identityKey = owner.getIdentityKey();
742	        String soundex = Soundex.encode(owner.getLastName());
743	        Integer matchId = this.clinicService.findAllOwners().stream()
744	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName()))
745	                && owner.getPostcode().equals(existing.getPostcode())
746	                && !identityKey.equals(existing.getIdentityKey()))
747	            .map(Owner::getId)
748	            .min(Integer::compareTo)
749	            .orElse(null);
750	        owner.setPossibleDuplicate(matchId != null);
751	        owner.setPossibleDuplicateOf(matchId);
752	    }
753	
754	    /**
755	     * Stamps the household's member count after this create ({@code householdSize}) onto every member of
756	     * the household - the existing owners that share the deterministic {@code householdId} and the new
757	     * one - so the shared size can be read back from any of them. The count is the number of existing
758	     * members plus the owner being created.
759	     *
760	     * @param owner the owner being created, with its deterministic {@code householdId} already set
761	     */
762	    private void stampHouseholdSize(Owner owner) {
763	        List<Owner> members = householdMembers(owner);
764	        int householdSize = members.size() + 1;
765	        owner.setHouseholdSize(householdSize);
766	        for (Owner member : members) {
767	            member.setHouseholdSize(householdSize);
768	            this.clinicService.saveOwner(member);
769	        }
770	    }
771	
772	    /**
773	     * The existing owners that belong to the same household as the given owner - those that share its
774	     * deterministic {@code householdId}. This is the single definition of "who is in this household",
775	     * shared by the household-size stamp and the membership-level cap. The owner being created is not
776	     * among them (it has not been saved yet); soft-deleted owners are included, so callers that need
777	     * only live members filter them out themselves.
778	     *
779	     * @param owner the owner being created, with its deterministic {@code householdId} already set
780	     * @return the existing same-household owners
781	     */
782	    private List<Owner> householdMembers(Owner owner) {
783	        String householdId = owner.getHouseholdId();
784	        return this.clinicService.findAllOwners().stream()
785	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
786	            .toList();
787	    }
788	
789	    /**
790	     * Caps the new owner's membership level so it cannot exceed one above the current maximum
791	     * membership level among the existing members of its household - the non-deleted owners that share
792	     * the deterministic {@code householdId}. The new owner's level is lowered to that ceiling only when
793	     * its derived level sits above it; otherwise it is left to be derived normally. When the household
794	     * has no existing member no cap applies and the level is left untouched.
795	     *
796	     * @param owner the owner being created, with its deterministic {@code householdId} and
797	     *     {@code householdSize} already set
798	     */
799	    private void capMembershipLevelToHousehold(Owner owner) {
800	        OptionalInt maxMemberLevel = householdMembers(owner).stream()
801	            .filter(existing -> !existing.isDeleted())
802	            .mapToInt(Owner::getMembershipLevel)
803	            .max();
804	        if (maxMemberLevel.isEmpty()) {
805	            return;
806	        }
807	        int cap = maxMemberLevel.getAsInt() + 1;
808	        if (owner.getMembershipLevel() > cap) {
809	            owner.setMembershipLevel(cap);
810	        }
811	    }
812	
813	    /**
814	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
815	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
816	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
817	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
818	     * shares a last name and postcode computes the same identifier and therefore the same household.
819	     *
820	     * @param lastName the last name of the household
821	     * @param postcode the postcode of the household, possibly {@code null}
822	     * @return the 12-character upper-case hex household identifier
823	     */
824	    private String computeHouseholdId(String lastName, String postcode) {
825	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
826	        try {
827	            byte[] digest = MessageDigest.getInstance("SHA-256")
828	                .digest(key.getBytes(StandardCharsets.UTF_8));
829	            StringBuilder hex = new StringBuilder(12);
830	            for (int i = 0; i < 6; i++) {
831	                hex.append(String.format("%02X", digest[i]));
832	            }
833	            return hex.toString();
834	        } catch (NoSuchAlgorithmException e) {
835	            throw new IllegalStateException("SHA-256 algorithm not available", e);
836	        }
837	    }
838	
839	    /**
840	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
841	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
842	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
843	     *
844	     * @param value the raw value, possibly {@code null}
845	     * @return the normalized value
846	     */
847	    private String normalizeForHousehold(String value) {
848	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
849	    }
850	
851	    /**
852	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
853	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
854	     * value yields an empty string.
855	     *
856	     * @param value the raw value, possibly {@code null}
857	     * @return the trimmed, whitespace-collapsed value
858	     */
859	    private String collapseWhitespace(String value) {
860	        if (value == null) {
861	            return "";
862	        }
863	        return value.trim().replaceAll("\\s+", " ");
864	    }
865	
866	    /**
867	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
868	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
869	     * is upper-cased, and common street-type abbreviations are expanded as whole words
870	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
871	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
872	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
873	     *
874	     * @param address the raw address value, possibly {@code null}
875	     * @return the normalized address
876	     */
877	    private String normalizeAddress(String address) {
878	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
879	        if (collapsed.isEmpty()) {
880	            return "";
881	        }
882	        String[] tokens = collapsed.split(" ");
883	        StringBuilder normalized = new StringBuilder();
884	        for (int i = 0; i < tokens.length; i++) {
885	            if (i > 0) {
886	                normalized.append(' ');
887	            }
888	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
889	        }
890	        return normalized.toString();
891	    }
892	
893	    /**
894	     * Applies the owner's address from the request, preferring the structured form over the flat one.
895	     * When a non-blank {@code addressLine1} is supplied it is normalized ({@link #normalizeAddress}) and
896	     * stored, along with the normalized {@code addressLine2} when present, and the stored {@code address}
897	     * is the composed string ({@link #composeAddress}). Otherwise the flat {@code address} input is
898	     * normalized and stored, and the structured lines are cleared. Normalization therefore applies to
899	     * whichever address fields are supplied, and everything that reads {@link Owner#getAddress()} sees
900	     * the structured address when present, falling back to the flat address.
901	     *
902	     * @param owner the owner being created
903	     * @param ownerFieldsDto the submitted owner fields
904	     */
905	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
906	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
907	        if (StringUtils.hasText(line1)) {
908	            String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
909	            String normalizedLine2 = StringUtils.hasText(line2) ? line2 : null;
910	            owner.setAddressLine1(line1);
911	            owner.setAddressLine2(normalizedLine2);
912	            owner.setAddress(composeAddress(line1, normalizedLine2));
913	        } else {
914	            owner.setAddressLine1(null);
915	            owner.setAddressLine2(null);
916	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
917	        }
918	    }
919	
920	    /**
921	     * Composes the stored-and-returned {@code address} string from the normalized structured lines: the
922	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
923	     * appended when the second line is present.
924	     *
925	     * @param line1 the normalized first address line
926	     * @param line2 the normalized second address line, or {@code null} when absent
927	     * @return the composed address string
928	     */
929	    private String composeAddress(String line1, String line2) {
930	        return line2 == null ? line1 : line1 + " " + line2;
931	    }
932	
933	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
934	    @Override
935	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
936	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
937	        if (currentOwner == null) {
938	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
939	        }
940	        currentOwner.setAddress(ownerFieldsDto.getAddress());
941	        currentOwner.setCity(ownerFieldsDto.getCity());
942	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
943	        currentOwner.setLastName(ownerFieldsDto.getLastName());
944	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
945	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
946	        this.clinicService.saveOwner(currentOwner);
947	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
948	    }
949	
950	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
951	    @Transactional
952	    @Override
953	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
954	        Owner owner = this.clinicService.findOwnerById(ownerId);
955	        if (owner == null) {
