963	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
964	    @Override
965	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
966	        Owner owner = this.clinicService.findOwnerById(ownerId);
967	        if (owner == null) {
968	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
969	        }
