131	     * {@link #getLocality() locality}: NSW->Australia/Sydney, VIC->Australia/Melbourne,
132	     * QLD->Australia/Brisbane. A locality not listed derives a {@code null} timezone.
133	     */
134	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
135	        "NSW", "Australia/Sydney",
136	        "VIC", "Australia/Melbourne",
137	        "QLD", "Australia/Brisbane");
138	
139	    /**
