714	    public void setPostcode(String postcode) {
715	        this.postcode = postcode;
716	    }
717	
718	    public Boolean getBulkSignupWarning() {
719	        return this.bulkSignupWarning;
720	    }
721	
722	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
723	        this.bulkSignupWarning = bulkSignupWarning;
724	    }
