    public void setPossibleDuplicate(Boolean possibleDuplicate) {
        this.possibleDuplicate = possibleDuplicate;
    }

    public Integer getPossibleDuplicateOf() {
        return this.possibleDuplicateOf;
    }

    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
        this.possibleDuplicateOf = possibleDuplicateOf;
    }

    /**
     * A consolidated risk indicator for the owner, derived from its other attributes. It is
     * {@code true} when any of the following hold, and {@code false} otherwise:
     * <ul>
     *   <li>the owner is a possible duplicate ({@link #getPossibleDuplicate() possibleDuplicate});</li>
     *   <li>its email domain is disposable-adjacent (see {@link #isDisposableAdjacentEmail()});</li>
     *   <li>its city is over its soft capacity ({@link #getCapacityWarning() capacityWarning}, the city
     *       already held 40 or more owners when this owner was created).</li>
     * </ul>
     *
     * @return whether the owner carries any of the risk conditions
     */
    public Boolean getRiskFlag() {
        return Boolean.TRUE.equals(this.possibleDuplicate)
            || Boolean.TRUE.equals(this.capacityWarning)
            || isDisposableAdjacentEmail();
    }

    /**
     * Whether the owner's email domain is <em>disposable-adjacent</em>: it shares the second-level name
     * of a known disposable mail provider ({@link #DISPOSABLE_EMAIL_DOMAINS}) without necessarily being
     * an exact match. This catches the common evasions of the exact-match create-time block - a subdomain
     * of a disposable provider (e.g. {@code mail.mailinator.com}) and a sibling top-level domain of one
     * (e.g. {@code mailinator.net}) - both of which resolve to the same second-level label
     * (e.g. {@code mailinator}). The comparison is case-insensitive. An absent or malformed email is not
     * disposable-adjacent.
     *
     * @return whether the owner's email domain is adjacent to a known disposable provider
     */
    private boolean isDisposableAdjacentEmail() {
        if (this.email == null || this.email.isBlank()) {
            return false;
        }
        int at = this.email.lastIndexOf('@');
        if (at < 0 || at == this.email.length() - 1) {
            return false;
        }
        String base = secondLevelLabel(this.email.substring(at + 1).toLowerCase(Locale.ROOT));
        if (base.isEmpty()) {
            return false;
        }
        for (String disposable : DISPOSABLE_EMAIL_DOMAINS) {
            if (base.equals(secondLevelLabel(disposable))) {
                return true;
            }
        }
        return false;
    }

    /**
     * The second-level label of a dot-separated domain - the label immediately before the final one
     * (e.g. {@code mailinator} for {@code mailinator.com}, {@code mail.mailinator.com} and
     * {@code mailinator.net} alike). A domain with no dot is returned unchanged.
     *
     * @param domain the lower-cased domain to inspect
     * @return the second-level label
     */
    private static String secondLevelLabel(String domain) {
        String[] labels = domain.split("\\.");
        if (labels.length < 2) {
            return domain;
        }
        return labels[labels.length - 2];
    }

    /**
     * Whether this owner has been soft-deleted. A newly created owner is not deleted
     * ({@code false}); the DELETE endpoint marks the owner deleted ({@code true}) while retaining the
     * row, and the create endpoint's duplicate and identity checks ignore owners flagged deleted.
     *
     * @return whether the owner has been soft-deleted
     */
    public boolean isDeleted() {
        return this.deleted;
    }

    public void setDeleted(boolean deleted) {
        this.deleted = deleted;
    }

    /**
     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
     */
    @PrePersist
    void onCreate() {
        this.registrationDate = resolveRegistrationDate(this.registrationDate);
    }

    /**
     * Resolves the effective registration date and rolls it onto a business day. An absent
     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
     * The resulting date is then rolled forward so it never falls on a weekend or a listed public
     * holiday: starting from the effective date, the date advances one day at a time while it lands
     * on a Saturday, a Sunday, or a date in {@link #PUBLIC_HOLIDAYS}, stopping on the first
     * non-holiday business day. A date already on a business day is returned unchanged.
     *
     * <p>This is the single definition of both the defaulting and the business-day roll, used
     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
     * stamps the owner and by the create endpoint that counts owners per business day.
     *
     * @param supplied the registration date from the request, or {@code null} when none was supplied
     * @return the effective registration date, guaranteed to fall on a non-holiday business day
     */
    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
        LocalDate effective = supplied != null ? supplied : LocalDate.now();
        while (!isBusinessDay(effective)) {
            effective = effective.plusDays(1);
        }
        return effective;
    }

    /**
     * The fixed list of public holidays that the registration date rolls past, alongside weekends.
     */
    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
        LocalDate.of(2026, 1, 1),
        LocalDate.of(2026, 1, 26),
        LocalDate.of(2026, 4, 25),
        LocalDate.of(2026, 12, 25),
        LocalDate.of(2026, 12, 28));

    /**
     * A business day is any date that is neither a weekend day nor a listed public holiday.
     */
    private static boolean isBusinessDay(LocalDate date) {
        DayOfWeek day = date.getDayOfWeek();
        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !PUBLIC_HOLIDAYS.contains(date);
    }

    protected Set<Pet> getPetsInternal() {
        if (this.pets == null) {
            this.pets = new HashSet<>();
        }
        return this.pets;
    }

    protected void setPetsInternal(Set<Pet> pets) {
        this.pets = pets;
    }

    public List<Pet> getPets() {
        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
        return Collections.unmodifiableList(sortedPets);
    }

    public void setPets(List<Pet> pets) {
        this.pets = new HashSet<>(pets);
    }

    public void addPet(Pet pet) {
        getPetsInternal().add(pet);
        pet.setOwner(this);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name) {
        return getPet(name, false);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name, boolean ignoreNew) {
        name = name.toLowerCase();
        for (Pet pet : getPetsInternal()) {
            if (!ignoreNew || !pet.isNew()) {
                String compName = pet.getName();
                compName = compName.toLowerCase();
                if (compName.equals(name)) {
                    return pet;
                }
            }
        }
        return null;
    }

    public Pet getPet(Integer petId) {
        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
    }

    @Override
    public String toString() {
        return new ToStringCreator(this)

            .append("id", this.getId())
            .append("new", this.isNew())
            .append("lastName", this.getLastName())
            .append("firstName", this.getFirstName())
            .append("address", this.address)
            .append("city", this.city)
            .append("telephone", this.telephone)
            .toString();
    }
}

